INSERT INTO `custom_otherdiv` VALUES (1,'IGEADI','IGEADI','IGEADI','IGEADI','<p><span style=\"color: rgb(5, 5, 5); font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; font-size: 15px; text-align: center; background-color: transparent;\">Instituto de Gestao de Equipamentos e Apoio ao Desenvolvimento Infrastruturas, Instituto Publico</span><br></p><p><br></p><p>Facebook:&nbsp;<a href=\"https://www.facebook.com/IGETL/?mibextid=ZbWKwL\" target=\"_blank\">https://www.facebook.com/IGETL/?mibextid=ZbWKwL</a></p>','<p>Facebook:&nbsp;<a href=\"https://www.facebook.com/IGETL/?mibextid=ZbWKwL\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255);\">https://www.facebook.com/IGETL/?mibextid=ZbWKwL</a><br></p>','<p>Facebook:&nbsp;<a href=\"https://www.facebook.com/IGETL/?mibextid=ZbWKwL\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255);\">https://www.facebook.com/IGETL/?mibextid=ZbWKwL</a><br></p>','others/IGEADI.jpg'),(2,'EDTL.E.P','EDTL.E.P','EDTL.E.P','EDTL.E.P','<p class=\"MsoNormal\" style=\"text-align:justify;tab-stops:58.2pt\"><span lang=\"EN-ID\">Electricidade de Timor-Leste, Empresa Pública (EDTL, E.P.) hanesan\r\nTimor-Leste nia Empreza Pública iha setór Eletricidade no Enerjia, estabelesidu\r\nbazeia ba Dekretu Lei Nu. 29/2020, 22 Julhu. EDTL, E.P. estabelese ho objetivu\r\nprinsipal atu hare no asegura funsionamento setor eletricidade bazeia ba\r\nPolitíka Governo Timor-Leste nian atu aselera asesu no fornesemento eletrisidade\r\nba públiku ba maior parte iha teritorio nasional, kria strutura hodi reforma\r\nsetor eletricidade hodi habelar no moderniza Sistema Nasionál Eletrisidade, no\r\nmós implementa jestaun atu hadia atendimentu públiku, hasa’e padraun kualidade\r\nno reliabilidade ho presu tuir kbi’it, ho konsiderasaun ba fizibilidade no\r\nsustantebilidade ba operasaun Empreza nian. EDTL, E.P. nia operasaun negósiu\r\nkompostu husi Produsaun, Transmisaun no Distribuisaun ho planu atu halo\r\ndiversifikasaun ba setór enejia renovável.</span></p><p class=\"MsoNormal\" style=\"text-align:justify;tab-stops:58.2pt\"><span lang=\"EN-ID\"><o:p><br></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify;tab-stops:58.2pt\"><span lang=\"EN-ID\"><o:p><span style=\"text-align: start; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 12pt; line-height: 17.12px;\">Website:&nbsp;</span><a href=\"https://edtl-ep.tl/\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255); text-align: start;\">https://edtl-ep.tl/</a><br></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify;tab-stops:58.2pt\"><span lang=\"EN-ID\"><o:p>Facebook: <a href=\"//www.facebook.com/EDTLEP2021/?mibextid=ZbWK\" target=\"_blank\">www.facebook.com/EDTLEP2021/?mibextid=ZbWK</a><br></o:p></span></p>','<p style=\"text-align: justify; \">Electricidade de Timor-Leste Empresa Pública (EDTL, E.P.) is the Timor-Leste’s State-Owned Company in Electricity and Energy Sector, established based on the Decree Law No. 29/2020, of 22 July. EDTL, E.P. was established with the main objective to oversee and ensure the functioning of electricity sector based on the Timor-Leste’s Government Policy to accelerate public access to the electricity and supply of electricity in a large part of the national territory, create a set of structuring measures for a reform of the electricity sector aimed at the expansion and modernization of the National Electricity System, as well as the management implementation to improve public services provided, raising standards of quality and reliability at the affordable prices, taking into account the feasibility and sustainability of its operations. EDTL, E.P.’s business operation consists of Generation, Transmission, and Distribution of Electricity and in planning for the energy diversification to renewables in the energy sector.</p><p style=\"text-align: justify; \"><br></p><p style=\"text-align: justify; \"><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; text-align: start; font-size: 12pt; line-height: 17.12px;\">Website:&nbsp;</span><a href=\"https://edtl-ep.tl/\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255); text-align: start;\">https://edtl-ep.tl/</a><br></p><p style=\"text-align: justify; \">Facebook:&nbsp;<a href=\"http://www.facebook.com/EDTLEP2021/?mibextid=ZbWK\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255);\">www.facebook.com/EDTLEP2021/?mibextid=ZbWK</a><br></p>','<p class=\"MsoNormal\" style=\"text-align:justify;tab-stops:58.2pt\"><span lang=\"EN-ID\">Electricidade de Timor-Leste Empresa Pública (EDTL, E.P.) is the\r\nTimor-Leste’s State-Owned Company in Electricity and Energy Sector, established\r\nbased on the Decree Law No. 29/2020, of 22 July. EDTL, E.P. was established\r\nwith the main objective to oversee and ensure the functioning of electricity\r\nsector based on the Timor-Leste’s Government Policy to accelerate public access\r\nto the electricity and supply of electricity in a large part of the national\r\nterritory, create a set of structuring measures for a reform of the electricity\r\nsector aimed at the expansion and modernization of the National Electricity\r\nSystem, as well as the management implementation to improve public services\r\nprovided, raising standards of quality and reliability at the affordable prices,\r\ntaking into account the feasibility and sustainability of its operations. EDTL,\r\nE.P.’s business operation consists of Generation, Transmission, and\r\nDistribution of Electricity and in planning for the energy diversification to\r\nrenewables in the energy sector.</span></p><p class=\"MsoNormal\" style=\"text-align:justify;tab-stops:58.2pt\"><span lang=\"EN-ID\"><o:p><br></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify;tab-stops:58.2pt\"><span lang=\"EN-ID\"><o:p><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; text-align: start; font-size: 12pt; line-height: 17.12px;\">Website:&nbsp;</span><a href=\"https://edtl-ep.tl/\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255); text-align: start;\">https://edtl-ep.tl/</a><br></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify;tab-stops:58.2pt\"><span lang=\"EN-ID\"><o:p>Facebook:&nbsp;<a href=\"http://www.facebook.com/EDTLEP2021/?mibextid=ZbWK\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255);\">www.facebook.com/EDTLEP2021/?mibextid=ZbWK</a><br></o:p></span></p>','others/edtl.png'),(3,'BTL.E.P','BTL.E.P','BTL.E.P','BTL.E.P','<p class=\"MsoNormal\"><span lang=\"EN-ID\">Bee Timor-Leste,\r\nEmpresa Pública<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span lang=\"EN-ID\">Bee Timor-Leste\r\nEmpresa Publiku (BTL, E.P.) mak kompañia utilidade públiku ida-ne\'ebé foin\r\nlalais ne\'e estabelese husi Governu Timor-Leste liuhusi Dekretu-Lei n.o.\r\n41/2020.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span lang=\"EN-ID\">&nbsp;</span><span style=\"background-color: transparent;\">Ami foun, maibé ho\r\nentuziazmu hodi hala\'o ami-nia servisu. Ami-nia knaar mak atu promove\r\nefisiénsia no sustentabilidade ne\'ebé boot liu ba implementasaun estratéjia\r\nGovernu nian hodi fornese bee moos no hadi\'a servisu saneamentu ba públiku.</span></p><p class=\"MsoNormal\"><span style=\"background-color: transparent;\"><br></span></p><p class=\"MsoNormal\"><span style=\"background-color: transparent;\">Website:&nbsp;</span><a href=\"https://btl.tl/\" target=\"_blank\">https://btl.tl/</a></p><p class=\"MsoNormal\"><span style=\"background-color: transparent;\">Facebook:&nbsp;</span><span style=\"background-color: transparent;\"><a href=\"https://www.facebook.com/BTLEP2021?mibextid=ZbWKwL\" target=\"_blank\">https://www.facebook.com/BTLEP2021?mibextid=ZbWKwL</a></span></p>','<p>-</p><p><br></p><p class=\"MsoNormal\"><span lang=\"EN-ID\"><span style=\"background-color: transparent;\">Website:&nbsp;</span><a href=\"https://btl.tl/\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255);\">https://btl.tl/</a><br></span></p><p class=\"MsoNormal\"><span lang=\"EN-ID\"><o:p><span style=\"background-color: transparent;\">Facebook:&nbsp;</span><span style=\"background-color: transparent;\"><a href=\"https://www.facebook.com/BTLEP2021?mibextid=ZbWKwL\" target=\"_blank\">https://www.facebook.com/BTLEP2021?mibextid=ZbWKwL</a></span></o:p></span></p>','<p class=\"MsoNormal\"><span lang=\"EN-ID\">Welcome to BTL,\r\nE.P - BTL, E.P Bee Timor-Leste Empressa Publica (BTL, E.P.) is a public utility\r\ncompany recently established by the Government of Timor-Leste through a Decree\r\nLaw no. 41/2020.<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-ID\">We are new, but\r\nenthusiastic in performing our tasks.<o:p></o:p></span></p><p>\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\"><span lang=\"EN-ID\">Our tasks are to\r\npromote greater efficiency and sustainability for the implementation of the\r\nGovernment\'s strategy in providing clean water and improved sanitation services\r\nto the public.</span></p><p class=\"MsoNormal\"><span lang=\"EN-ID\"><o:p><br></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-ID\"><o:p><span style=\"background-color: transparent;\">Website:&nbsp;</span><a href=\"https://btl.tl/\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255);\">https://btl.tl/</a><br></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-ID\"><o:p><span style=\"background-color: transparent;\">Facebook:&nbsp;</span><span style=\"background-color: transparent;\"><a href=\"https://www.facebook.com/BTLEP2021?mibextid=ZbWKwL\" target=\"_blank\">https://www.facebook.com/BTLEP2021?mibextid=ZbWKwL</a></span><br></o:p></span></p>','others/bee_uBpZOAU.gif');
